#include <bits/stdc++.h>
using namespace std;

using int64 = long long;
const int64 MOD = 1000000007LL;

int64 powmod(int64 base, int64 exp, int64 mod) {
  int64 res = 1;
  while (exp != 0) {
    if (exp % 2 != 0) res = (res * base) % mod;
    base = (base * base) % mod;
    exp /= 2;
  }
  return res;
}

int main() {
  ios_base::sync_with_stdio(false);
  cin.tie(0);

  int64 p, k;
  while (cin >> p >> k) {
    if (k == 0) {
      cout << powmod(p, p - 1, MOD) << '\n';
      continue;
    }
    if (k == 1) {
      cout << powmod(p, p, MOD) << '\n';
      continue;
    }

    deque<bool> visited(p);
    int64 answer = 0;

    for (int64 start = 1; start < p; ++start) {
      if (visited[start]) continue;

      int64 x = start;
      int64 length = 0;

      while (!visited[x]) {
        ++length;
        visited[x] = true;
        x = (x * k) % p;
      }

      if (powmod(k, length, p) == 1) ++answer;
    }

    cout << powmod(p, answer, MOD) << '\n';
  }

  return 0;
}
